"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[7392],{53781(e,a,i){i.r(a),i.d(a,{assets:()=>c,contentTitle:()=>t,default:()=>u,frontMatter:()=>n,metadata:()=>s,toc:()=>d});const s=JSON.parse('{"id":"cursos/docker/modulos/networking-service-mesh/cuestionario","title":"Cuestionario M19 \u2014 Networking y Service Mesh","description":"Instrucci\xf3n: Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del","source":"@site/docs/cursos/docker/modulos/19-networking-service-mesh/cuestionario.md","sourceDirName":"cursos/docker/modulos/19-networking-service-mesh","slug":"/cursos/docker/modulos/networking-service-mesh/cuestionario","permalink":"/sasf-temarios/cursos/docker/modulos/networking-service-mesh/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/docker/modulos/networking-service-mesh/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/docker/modulos/networking-service-mesh/ejercicio"}}');var r=i(74848),o=i(28453);const n={sidebar_label:"Cuestionario"},t="Cuestionario M19 \u2014 Networking y Service Mesh",c={},d=[{value:"1. [Investigar] \xbfQu\xe9 es exactamente el &quot;Gateway API&quot; de Kubernetes y c\xf3mo mejora sobre el Ingress tradicional? \xbfPor qu\xe9 se cre\xf3 un nuevo est\xe1ndar en lugar de extender Ingress?",id:"1-investigar-qu\xe9-es-exactamente-el-gateway-api-de-kubernetes-y-c\xf3mo-mejora-sobre-el-ingress-tradicional-por-qu\xe9-se-cre\xf3-un-nuevo-est\xe1ndar-en-lugar-de-extender-ingress",level:3},{value:"2. [Investigar] \xbfQu\xe9 es exactamente &quot;ambient mesh&quot; (Istio Ambient) y c\xf3mo difiere del modelo sidecar tradicional? \xbfQu\xe9 ventajas de rendimiento y operaciones ofrece?",id:"2-investigar-qu\xe9-es-exactamente-ambient-mesh-istio-ambient-y-c\xf3mo-difiere-del-modelo-sidecar-tradicional-qu\xe9-ventajas-de-rendimiento-y-operaciones-ofrece",level:3},{value:"3. [Investigar] \xbfC\xf3mo funciona exactamente Cilium como CNI y como replacement de kube-proxy usando eBPF? \xbfQu\xe9 es el &quot;Cilium Cluster Mesh&quot; para multi-cluster?",id:"3-investigar-c\xf3mo-funciona-exactamente-cilium-como-cni-y-como-replacement-de-kube-proxy-usando-ebpf-qu\xe9-es-el-cilium-cluster-mesh-para-multi-cluster",level:3},{value:"4. [Investigar] \xbfQu\xe9 es exactamente &quot;SPIFFE&quot; y c\xf3mo se relaciona con mTLS en service meshes? \xbfPor qu\xe9 la identidad de servicio es fundamental para zero trust?",id:"4-investigar-qu\xe9-es-exactamente-spiffe-y-c\xf3mo-se-relaciona-con-mtls-en-service-meshes-por-qu\xe9-la-identidad-de-servicio-es-fundamental-para-zero-trust",level:3},{value:"5. [Conectar] La clase menciona NetworkPolicy. \xbfQu\xe9 diferencia hay entre NetworkPolicy de K8s y las pol\xedticas de seguridad de un Service Mesh (Istio AuthorizationPolicy)? \xbfCu\xe1ndo usar una sobre la otra?",id:"5-conectar-la-clase-menciona-networkpolicy-qu\xe9-diferencia-hay-entre-networkpolicy-de-k8s-y-las-pol\xedticas-de-seguridad-de-un-service-mesh-istio-authorizationpolicy-cu\xe1ndo-usar-una-sobre-la-otra",level:3},{value:"6. [Conectar] \xbfC\xf3mo funciona exactamente el mTLS en un Service Mesh? \xbfQu\xe9 es el &quot;auto mTLS&quot; y c\xf3mo resuelve el problema de migraci\xf3n gradual?",id:"6-conectar-c\xf3mo-funciona-exactamente-el-mtls-en-un-service-mesh-qu\xe9-es-el-auto-mtls-y-c\xf3mo-resuelve-el-problema-de-migraci\xf3n-gradual",level:3},{value:"7. [Conectar] \xbfQu\xe9 es exactamente &quot;kube-proxy&quot; y c\xf3mo se diferencia de los proxies de Service Mesh? \xbfQu\xe9 significa que kube-proxy opera a L4 y el Service Mesh a L7?",id:"7-conectar-qu\xe9-es-exactamente-kube-proxy-y-c\xf3mo-se-diferencia-de-los-proxies-de-service-mesh-qu\xe9-significa-que-kube-proxy-opera-a-l4-y-el-service-mesh-a-l7",level:3},{value:"8. [Cuestionar] \xbfEs Service Mesh (Istio/Linkerd) una necesidad real o un lujo para la mayor\xeda de las empresas? \xbfA partir de qu\xe9 escala se justifica?",id:"8-cuestionar-es-service-mesh-istiolinkerd-una-necesidad-real-o-un-lujo-para-la-mayor\xeda-de-las-empresas-a-partir-de-qu\xe9-escala-se-justifica",level:3},{value:"9. [Cuestionar] CNI plugins: \xbfCalico, Cilium, o Flannel? \xbfC\xf3mo elegir el CNI correcto para tu cluster?",id:"9-cuestionar-cni-plugins-calico-cilium-o-flannel-c\xf3mo-elegir-el-cni-correcto-para-tu-cluster",level:3},{value:"10. [Cuestionar] \xbfEs el modelo de red de K8s (&quot;todos los Pods pueden comunicarse&quot;) un riesgo de seguridad inherente? \xbfDeber\xeda cambiarse el default a &quot;deny all&quot;?",id:"10-cuestionar-es-el-modelo-de-red-de-k8s-todos-los-pods-pueden-comunicarse-un-riesgo-de-seguridad-inherente-deber\xeda-cambiarse-el-default-a-deny-all",level:3}];function l(e){const a={code:"code",h1:"h1",h3:"h3",header:"header",hr:"hr",p:"p",strong:"strong",...(0,o.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(a.header,{children:(0,r.jsx)(a.h1,{id:"cuestionario-m19--networking-y-service-mesh",children:"Cuestionario M19 \u2014 Networking y Service Mesh"})}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Instrucci\xf3n"}),": Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del\r\ncontenido de la clase. No alcanza con lo visto en ",(0,r.jsx)(a.code,{children:"clase.md"}),".\r\nFundament\xe1 tus respuestas con fuentes, autores o ejemplos concretos."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"1-investigar-qu\xe9-es-exactamente-el-gateway-api-de-kubernetes-y-c\xf3mo-mejora-sobre-el-ingress-tradicional-por-qu\xe9-se-cre\xf3-un-nuevo-est\xe1ndar-en-lugar-de-extender-ingress",children:'1. [Investigar] \xbfQu\xe9 es exactamente el "Gateway API" de Kubernetes y c\xf3mo mejora sobre el Ingress tradicional? \xbfPor qu\xe9 se cre\xf3 un nuevo est\xe1ndar en lugar de extender Ingress?'}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": Gateway API (K8s SIG-Network, 2020+) es un est\xe1ndar de pr\xf3xima generaci\xf3n para enrutamiento L4-L7 en K8s que reemplaza/ complementa Ingress. Introduce recursos m\xe1s expresivos y role-oriented: 1) ",(0,r.jsx)(a.code,{children:"GatewayClass"})," (infra admin): define qu\xe9 controller (istio, nginx, contour) y qu\xe9 tipo de load balancer, 2) ",(0,r.jsx)(a.code,{children:"Gateway"})," (cluster operator): instancia espec\xedfica escuchando en puertos con TLS, 3) ",(0,r.jsx)(a.code,{children:"HTTPRoute"})," (developer): reglas de enrutamiento por host, path, headers, weight, y filtros (rate limiting, retries). Mejoras sobre Ingress: 1) Role-oriented (RBAC granular: developer define routes, infra admin define gateways), 2) Soporte L4 (TCP, UDP, gRPC) adem\xe1s de HTTP, 3) Traffic splitting (pesos para canary), 4) Backend policy (timeouts, health checks), 5) Extensibilidad (custom filters). No se extendi\xf3 Ingress porque Ingress es un recurso plano (todos los campos en un solo objeto), mientras Gateway API separa responsabilidades."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": Gateway API es mantenido por el mismo SIG-Network que mantiene Ingress (Tim Hockin, Bowei Du, Rob Scott). La motivaci\xf3n: Ingress qued\xf3 limitado (soporte de features var\xeda por controller con annotations propietarias). Gateway API estandariza features avanzadas (traffic splitting, header matching) que antes requer\xedan annotations espec\xedficas de nginx/traefik. Los controllers migran gradualmente: nginx-gateway-fabric, Istio (ambient mesh), Contour, y Traefik ya soportan Gateway API."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"2-investigar-qu\xe9-es-exactamente-ambient-mesh-istio-ambient-y-c\xf3mo-difiere-del-modelo-sidecar-tradicional-qu\xe9-ventajas-de-rendimiento-y-operaciones-ofrece",children:'2. [Investigar] \xbfQu\xe9 es exactamente "ambient mesh" (Istio Ambient) y c\xf3mo difiere del modelo sidecar tradicional? \xbfQu\xe9 ventajas de rendimiento y operaciones ofrece?'}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": Istio Ambient (introducido en Istio 1.18, 2023) es un nuevo modo de service mesh que NO requiere un sidecar por Pod. En lugar de inyectar un proxy Envoy en cada Pod, Ambient divide la funcionalidad en dos capas: 1) ",(0,r.jsx)(a.strong,{children:"ztunnel"})," (zero trust tunnel, por nodo): proxy L4 que maneja mTLS, autenticaci\xf3n, y TCP routing entre nodos, sin parsear HTTP. 2) ",(0,r.jsx)(a.strong,{children:"waypoint proxy"})," (opcional, por service account): proxy L7 que maneja HTTP policies, traffic management, y telemetr\xeda, solo cuando se necesita. El sidecar tradicional (Envoy por Pod) requiere un proxy extra por cada Pod, consumiendo recursos (CPU/memoria) y agregando latencia. Ambient elimina el sidecar de Pods que no necesitan L7, reduciendo el overhead de recursos (ztunnel es compartido por todos los Pods del nodo) y simplificando operaciones (no hay que inyectar, actualizar, o debuggear sidecars individuales)."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": Ambient fue presentado por Solo.io y Google (Istio maintainers) en KubeCon 2022 como respuesta a las cr\xedticas de complejidad de sidecars. Ztunnel usa eBPF y el kernel networking para enrutamiento L4 eficiente (sin proxy user-space para tr\xe1fico L4). Waypoint es un proxy Envoy por service account (no por Pod), reduciendo el n\xfamero total de proxies en el cluster. Ambient es backward-compatible con sidecar (pueden coexistir). Linkerd (Buoyant) respondi\xf3 con un modelo similar (Linkerd 2.14+)."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"3-investigar-c\xf3mo-funciona-exactamente-cilium-como-cni-y-como-replacement-de-kube-proxy-usando-ebpf-qu\xe9-es-el-cilium-cluster-mesh-para-multi-cluster",children:'3. [Investigar] \xbfC\xf3mo funciona exactamente Cilium como CNI y como replacement de kube-proxy usando eBPF? \xbfQu\xe9 es el "Cilium Cluster Mesh" para multi-cluster?'}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": Cilium como CNI: 1) Asigna IPs a Pods (usando el IPAM de K8s o su propio IPAM), 2) Configura routing entre nodos (con eBPF, sin overlay o con direct routing via BGP), 3) Reemplaza kube-proxy: implementa Service load balancing en eBPF con mapas hash O(1) en lugar de iptables O(n). Para un Service ClusterIP, Cilium inserta un programa eBPF que hace DNAT del ClusterIP al endpoint Pod IP directamente en el kernel, sin reglas iptables. Cilium Cluster Mesh: conecta m\xfaltiples clusters K8s con routing directo de Pod IPs entre clusters (sin NAT, sin gateways), usando eBPF para encriptaci\xf3n (WireGuard/IPsec) y pol\xedticas de red globales. Los Pods en cluster A pueden comunicarse con Pods en cluster B usando sus IPs nativas, con mTLS y NetworkPolicy cross-cluster."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),': Cilium (Isovalent/Cisco, CNCF graduado) es el CNI m\xe1s avanzado en eBPF. Thomas Graf y el equipo de Isovalent demostraron que eBPF reemplaza iptables con rendimiento 10-100x mejor para Service load balancing. Cluster Mesh usa el concepto de "identity" (basado en labels de Pod) que es global entre clusters. Esto habilita multi-cluster service routing y failover. Para NetworkPolicy: Cilium puede aplicar pol\xedticas a nivel de API (HTTP/gRPC/Kafka) usando eBPF para inspeccionar tr\xe1fico L7 sin sidecar.']}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"4-investigar-qu\xe9-es-exactamente-spiffe-y-c\xf3mo-se-relaciona-con-mtls-en-service-meshes-por-qu\xe9-la-identidad-de-servicio-es-fundamental-para-zero-trust",children:'4. [Investigar] \xbfQu\xe9 es exactamente "SPIFFE" y c\xf3mo se relaciona con mTLS en service meshes? \xbfPor qu\xe9 la identidad de servicio es fundamental para zero trust?'}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": SPIFFE (Secure Production Identity Framework for Everyone) es un est\xe1ndar CNCF que define c\xf3mo identificar servicios de manera criptogr\xe1fica en entornos cloud-native. SPIFFE ID es un URI como ",(0,r.jsx)(a.code,{children:"spiffe://cluster.local/ns/default/sa/myservice"})," que identifica un\xedvocamente un servicio (basado en su ServiceAccount, namespace, y trust domain). SPIRE (la implementaci\xf3n de SPIFFE) emite certificados X.509 o JWTs que prueban esa identidad. En service meshes (Istio, Linkerd, Consul Connect), los sidecars usan certificados SPIFFE para mTLS: el proxy cliente verifica que el proxy servidor tiene un certificado con la identidad esperada. Zero trust se implementa porque la confianza se basa en identidad criptogr\xe1fica (SPIFFE ID en certificado), no en IP o ubicaci\xf3n de red."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": SPIFFE fue creado por Google, Netflix, Uber, y otras empresas (Evan Gilman, Douglas Reid). La especificaci\xf3n define: SPIFFE ID (identidad), SVID (documento que prueba la identidad), y SPIRE (implementaci\xf3n). En Istio, istiod act\xfaa como SPIRE server emitiendo SVIDs a cada sidecar Envoy. En Linkerd, el control plane emite identidades con su propia CA. SPIFFE es la base de autenticaci\xf3n en mTLS: sin identidad criptogr\xe1fica, mTLS solo cifra pero no autentica qui\xe9n es el peer."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"5-conectar-la-clase-menciona-networkpolicy-qu\xe9-diferencia-hay-entre-networkpolicy-de-k8s-y-las-pol\xedticas-de-seguridad-de-un-service-mesh-istio-authorizationpolicy-cu\xe1ndo-usar-una-sobre-la-otra",children:"5. [Conectar] La clase menciona NetworkPolicy. \xbfQu\xe9 diferencia hay entre NetworkPolicy de K8s y las pol\xedticas de seguridad de un Service Mesh (Istio AuthorizationPolicy)? \xbfCu\xe1ndo usar una sobre la otra?"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),': NetworkPolicy (K8s nativa): opera a L3/L4. Reglas basadas en IPs, namespaces, y puertos. Ejemplo: "Permitir tr\xe1fico TCP desde namespace ',(0,r.jsx)(a.code,{children:"frontend"})," a Pods con label ",(0,r.jsx)(a.code,{children:"app: backend"}),' en puerto 8080". Simple, eficiente (implementado por CNI/iables/eBPF), pero no entiende HTTP/gRPC. AuthorizationPolicy (Istio): opera a L7. Reglas basadas en identidad SPIFFE, paths HTTP, headers, m\xe9todos, y claims JWT. Ejemplo: "Permitir GET a /api/users solo desde servicios con ServiceAccount ',(0,r.jsx)(a.code,{children:"web"}),'". AuthorizationPolicy requiere Service Mesh (sidecar). Usar NetworkPolicy cuando: solo necesit\xe1s segmentaci\xf3n L3/L4 b\xe1sica, sin dependencia de Service Mesh. Usar AuthorizationPolicy cuando necesit\xe1s: pol\xedticas a nivel de API, autenticaci\xf3n JWT, rate limiting por usuario, o auditor\xeda L7.']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": La mejor pr\xe1ctica es defensa en profundidad: NetworkPolicy para segmentaci\xf3n b\xe1sica (defensa L3/L4, m\xe1s robusta porque no depende de sidecar), AuthorizationPolicy para defensa L7 (m\xe1s granular pero requiere Service Mesh). Un atacante que evite el sidecar ser\xe1 bloqueado por NetworkPolicy (L3/L4). Un atacante que tenga acceso a la red ser\xe1 limitado por AuthorizationPolicy (no puede hacer requests a paths no autorizados)."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"6-conectar-c\xf3mo-funciona-exactamente-el-mtls-en-un-service-mesh-qu\xe9-es-el-auto-mtls-y-c\xf3mo-resuelve-el-problema-de-migraci\xf3n-gradual",children:'6. [Conectar] \xbfC\xf3mo funciona exactamente el mTLS en un Service Mesh? \xbfQu\xe9 es el "auto mTLS" y c\xf3mo resuelve el problema de migraci\xf3n gradual?'}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),': mTLS en Service Mesh: 1) El control plane (istiod, Linkerd) emite certificados X.509 a cada proxy sidecar (identidad SPIFFE), 2) Cuando el sidecar cliente se conecta al sidecar servidor, ambos presentan sus certificados, 3) El sidecar cliente verifica que el certificado del servidor es v\xe1lido y corresponde a la identidad esperada (seg\xfan la pol\xedtica), 4) La conexi\xf3n se cifra con TLS. "Auto mTLS" (Istio) / "permissive mode": permite que un servicio acepte tanto tr\xe1fico mTLS (desde sidecars) como tr\xe1fico plaintext (desde servicios sin sidecar, durante la migraci\xf3n). Esto resuelve la migraci\xf3n gradual: pod\xe9s desplegar el mesh incrementalmente sin romper comunicaci\xf3n entre servicios con y sin sidecar.']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),': El "auto mTLS" de Istio usa un feature llamado "traffic shifting": cuando un sidecar detecta que el peer tambi\xe9n tiene sidecar, hace mTLS. Cuando detecta que el peer no tiene, hace plaintext. Esto permite migrar una flota de servicios a Service Mesh uno por uno, sin un "flag day" (d\xeda donde todos migran simult\xe1neamente). Linkerd tiene un feature similar (identity-based routing con fallback).']}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"7-conectar-qu\xe9-es-exactamente-kube-proxy-y-c\xf3mo-se-diferencia-de-los-proxies-de-service-mesh-qu\xe9-significa-que-kube-proxy-opera-a-l4-y-el-service-mesh-a-l7",children:'7. [Conectar] \xbfQu\xe9 es exactamente "kube-proxy" y c\xf3mo se diferencia de los proxies de Service Mesh? \xbfQu\xe9 significa que kube-proxy opera a L4 y el Service Mesh a L7?'}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": kube-proxy (componente de K8s, corre en cada nodo) implementa Service abstraction a nivel L4: mantiene reglas iptables/IPVS que mapean ClusterIP (VIP) \u2192 Pod IPs. Opera a nivel TCP/UDP (L4): balancea conexiones, no entiende HTTP, no puede hacer retries, circuit breaking, o routing por headers. Service Mesh proxies (Envoy, linkerd-proxy, sidecar) operan a L7: entienden HTTP/1.1, HTTP/2, gRPC. Pueden: 1) Enrutar basado en headers/path (no solo IP), 2) Hacer retries y timeouts, 3) Traffic splitting (canary), 4) Colectar m\xe9tricas por endpoint (latencia, status codes), 5) Aplicar pol\xedticas de seguridad L7 (RBAC por API path). kube-proxy es esencial para networking b\xe1sico en K8s. Service Mesh agrega L7 encima."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": kube-proxy usa iptables (modo por defecto) o IPVS. En iptables mode, KUBE-SERVICES chain contiene reglas para cada Service (DNAT del ClusterIP a un endpoint Pod IP). Con 1000 Services, hay ~5000+ reglas que se eval\xfaan para cada paquete (O(n)). Service Mesh proxys operan a L7 y agregan overhead de procesamiento por request (~1-5ms), pero habilitan features avanzadas que kube-proxy no puede."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"8-cuestionar-es-service-mesh-istiolinkerd-una-necesidad-real-o-un-lujo-para-la-mayor\xeda-de-las-empresas-a-partir-de-qu\xe9-escala-se-justifica",children:"8. [Cuestionar] \xbfEs Service Mesh (Istio/Linkerd) una necesidad real o un lujo para la mayor\xeda de las empresas? \xbfA partir de qu\xe9 escala se justifica?"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": Para empresas con <10 microservicios, Service Mesh es overkill: la complejidad de operar Istio/Linkerd supera los beneficios. mTLS y observabilidad L7 pueden implementarse con soluciones m\xe1s simples (cert-manager para TLS, OpenTelemetry para tracing, Prometheus para m\xe9tricas). Service Mesh se justifica cuando: 1) 20+ microservicios con comunicaci\xf3n compleja, 2) Necesit\xe1s trazabilidad end-to-end autom\xe1tica sin instrumentar cada app, 3) Requisitos de seguridad requieren mTLS universal y pol\xedticas de acceso L7, 4) Necesit\xe1s traffic management avanzado (canary, dark launches, fault injection). La complejidad operativa de Istio es real (sidecars, debugging de red con dos proxies adicionales por llamada). Linkerd es m\xe1s simple y ligero (proxy en Rust, zero config mTLS), siendo una mejor opci\xf3n para empresas que reci\xe9n adoptan Service Mesh."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),': William Morgan (CEO Buoyant, creador de Linkerd) argumenta que Linkerd fue dise\xf1ado para ser "un service mesh que no requiere un equipo dedicado", justamente porque Istio es demasiado complejo para la mayor\xeda. Istio, por otro lado, tiene features que Linkerd no (Wasm plugins, multi-cluster avanzado, Envoy ecosystem). La decisi\xf3n: \xbfnecesit\xe1s las features avanzadas de Istio y ten\xe9s equipo para operarlo? Si no, Linkerd o incluso no usar mesh.']}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"9-cuestionar-cni-plugins-calico-cilium-o-flannel-c\xf3mo-elegir-el-cni-correcto-para-tu-cluster",children:"9. [Cuestionar] CNI plugins: \xbfCalico, Cilium, o Flannel? \xbfC\xf3mo elegir el CNI correcto para tu cluster?"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": Flannel: el m\xe1s simple, overlay VXLAN/host-gw. No soporta NetworkPolicy (necesita extensiones como Canal). Ideal para desarrollo, aprendizaje, y clusters peque\xf1os sin requisitos de seguridad. Calico: usa BGP puro (sin overlay, mejor rendimiento) o VXLAN/IPIP. Soporta NetworkPolicy y Calico NetworkPolicy (m\xe1s expresivo que K8s NetworkPolicy). Ideal para producci\xf3n con alta performance y network security. Cilium: usa eBPF (m\xe1ximo rendimiento, L7 observability sin sidecar). Soporta NetworkPolicy, API-level security, y replacement de kube-proxy. Ideal para producci\xf3n avanzada con service mesh integrado, multi-cluster, y seguridad L7. Elecci\xf3n: Flannel para simplicidad, Calico para performance + seguridad, Cilium para lo m\xe1s avanzado."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": El benchmark de CNI (KubeCon 2023, Isovalent) mostr\xf3 que Cilium eBPF tiene el mejor rendimiento y menor latencia. Calico BGP es similar en rendimiento (sin overhead de overlay). Flannel es el m\xe1s usado por simplicidad, pero sin NetworkPolicy no es apto para producci\xf3n con requisitos de seguridad. Canal (Calico + Flannel) combina simplicidad de Flannel con NetworkPolicy de Calico. La tendencia: Cilium est\xe1 ganando adopci\xf3n r\xe1pidamente (default en GKE Dataplane V2, EKS-A, Azure CNI)."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"10-cuestionar-es-el-modelo-de-red-de-k8s-todos-los-pods-pueden-comunicarse-un-riesgo-de-seguridad-inherente-deber\xeda-cambiarse-el-default-a-deny-all",children:'10. [Cuestionar] \xbfEs el modelo de red de K8s ("todos los Pods pueden comunicarse") un riesgo de seguridad inherente? \xbfDeber\xeda cambiarse el default a "deny all"?'}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": El modelo default-allow es un riesgo: un Pod comprometido puede escanear y atacar cualquier otro Pod en el cluster (todos los Pods son alcanzables sin NAT). En contraste, Docker bridge default est\xe1 aislado (solo comunicaci\xf3n entre contenedores en la misma red). El modelo de K8s fue dise\xf1ado para simplicidad (Borg, el predecesor de K8s, tambi\xe9n era flat network) antes de que la seguridad multi-tenant fuera prioritaria. Hoy, la mejor pr\xe1ctica es: 1) Implementar NetworkPolicy deny-all por defecto en cada namespace, 2) Cada aplicaci\xf3n declara expl\xedcitamente qu\xe9 comunicaci\xf3n necesita (allow list). Pero cambiar el default a deny-all romper\xeda compatibilidad hacia atr\xe1s. Herramientas como Kyverno/OPA Gatekeeper pueden forzar pol\xedticas de red por defecto."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": La comunidad de K8s ha debatido esto por a\xf1os (issue #1246, 2015). La conclusi\xf3n es que cambiar el default romper\xeda demasiados clusters existentes. En cambio, K8s agreg\xf3 NetworkPolicy como mecanismo para implementar deny-all. Para nuevos clusters, se recomienda: habilitar NetworkPolicy desde el d\xeda 1, usar un admission controller que rechace Pods sin NetworkPolicy, y usar service mesh para mTLS entre Pods (defensa en profundidad)."]})]})}function u(e={}){const{wrapper:a}={...(0,o.R)(),...e.components};return a?(0,r.jsx)(a,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}},28453(e,a,i){i.d(a,{R:()=>n,x:()=>t});var s=i(96540);const r={},o=s.createContext(r);function n(e){const a=s.useContext(o);return s.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:n(e.components),s.createElement(o.Provider,{value:a},e.children)}}}]);